mapper.select:
SELECT 
FROM practice_module m
LEFT JOIN sys_dept d ON d.dept_id = m.dept_id AND d.del_flag = '0'

    m.deleted = 0

        AND m.dept_id = #{scopeDeptId}


        AND m.dept_id = #{deptId}


        AND m.status = #{status}


        AND (m.name LIKE CONCAT('%', #{name}, '%')
             OR m.description LIKE CONCAT('%', #{name}, '%'))


ORDER BY m.sort_no ASC, m.id ASC

SELECT m.id, m.dept_id, m.name, m.status, m.deleted
FROM practice_module m
WHERE m.deleted = 0
  AND m.dept_id = #{deptId}
  AND m.name = #{name}

    AND m.id != #{excludeId}

LIMIT 1

SELECT FROM practice_module m LEFT JOIN sys_dept d ON d.dept_id = m.dept_id AND d.del_flag = '0' WHERE m.deleted = 0 AND m.dept_id = #{deptId}
AND m.status = 1
ORDER BY m.sort_no ASC, m.id ASC
